export const config={id:'signal-letterpress',title:'信号成字',subtitle:'Make room for wonder',description:'散落的字母沿各自轨迹归位，停留成一张有呼吸的活版海报。',category:'coding-motion',useCase:'动态字体 · 片头设计 · 品牌宣言',accent:'#e75932',duration:10,parameter:{label:'初始散开幅度',min:0,max:100,step:1,value:65,unit:'%'}};
const words=['MAKE','ROOM','FOR','WONDER'];
export function letterState(t,value){let n=0;const time=((t%10)+10)%10;return words.flatMap((word,row)=>[...word].map((char,col)=>{const i=n++,local=Math.max(0,Math.min(1,(time-.045*i)/2.7)),returnPhase=Math.max(0,Math.min(1,(time-8)/2)),p=(1-Math.pow(1-local,4))*(1-returnPhase*returnPhase*(3-2*returnPhase)),spread=Math.max(0,Math.min(100,value))/100;const x=105+col*(row===3?150:177),y=257+row*132;return{char,row,x:x+(1-p)*Math.sin(i*2.4+1)*230*spread,y:y+(1-p)*Math.cos(i*1.7)*170*spread,rotation:(1-p)*Math.sin(i*3)*.7*spread};}));}
export function render(c,{t,value,width,height}){c.save();c.scale(width/1200,height/800);c.fillStyle='#ede9dd';c.fillRect(0,0,1200,800);c.fillStyle='#171f2a';c.fillRect(40,39,1120,3);c.font='13px monospace';c.fillText('SIGNAL PRESS',55,74);c.fillText('TYPE EXPERIMENT / 003',890,74);c.fillStyle='#e45b35';c.fillRect(887,105,245,435);
// Registration and composition marks belong to the print, not the player.
c.strokeStyle='#17202b40';c.lineWidth=1;for(const [x,y]of [[52,110],[1147,110],[52,702],[1147,702]]){c.beginPath();c.moveTo(x-9,y);c.lineTo(x+9,y);c.moveTo(x,y-9);c.lineTo(x,y+9);c.stroke();}for(let y=265;y<690;y+=132){c.strokeStyle='#28344722';c.beginPath();c.moveTo(77,y);c.lineTo(1124,y);c.stroke();}
for(const l of letterState(t,value)){c.save();c.translate(l.x,l.y);c.rotate(l.rotation);c.font=`900 ${l.row===3?151:164}px sans-serif`;c.fillStyle='#e45b35';c.fillText(l.char,3,2);c.fillStyle='#15222a';c.fillText(l.char,0,0);c.restore();}
// A narrow editorial column makes the deliberately empty space meaningful.
c.save();c.translate(1080,148);c.rotate(Math.PI/2);c.fillStyle='#efeadd';c.font='14px monospace';c.fillText('LEAVE A LITTLE SPACE',0,0);c.fillText('FOR THE UNEXPECTED.',0,24);c.restore();c.fillStyle='#18252d';c.font='14px "Noto Sans CJK SC", sans-serif';c.fillText('给奇想，留一席之地。',79,743);c.font='11px monospace';c.fillText('ORIGINAL WORDS / CODE-DRIVEN TYPE',785,744);c.strokeStyle='#17202b';c.beginPath();c.moveTo(79,710);c.lineTo(1126,710);c.stroke();
// Tiny printer's color marks.
['#17252d','#e45b35','#cfb78c'].forEach((v,i)=>{c.fillStyle=v;c.fillRect(1093+i*13,775,9,9);});c.restore();}
